import{d as a}from"./index-Ddkxz7CW.js";const c={getAll:async t=>{try{return((await a.get("/categories",{params:{limit:1e3,page:1,...t}})).data.data||[]).map(r=>({id:r.id||r._id,name:r.name,slug:r.slug,status:r.status,createdAt:r.createdAt||r.created_at}))}catch(e){throw console.error("Failed to fetch categories:",e),e}},create:async t=>{try{return(await a.post("/categories",t)).data}catch(e){throw new Error(e.response?.data?.message||"Failed to create category")}},update:async(t,e)=>{try{return(await a.put(`/categories/${t}`,e)).data}catch(r){throw new Error(r.response?.data?.message||"Failed to update category")}},delete:async t=>{try{await a.delete(`/categories/${t}`)}catch{throw new Error("Failed to delete category")}},bulkDelete:async t=>{try{await a.post("/categories/bulk-delete",{ids:t})}catch{throw new Error("Failed to delete selected categories")}},bulkUpdateStatus:async(t,e)=>{try{await a.post("/categories/bulk-update",{ids:t,status:e})}catch{throw new Error("Failed to update status")}},export:async t=>{try{const e=await a.get("/categories/export",{params:{format:t},responseType:"blob"}),r=window.URL.createObjectURL(new Blob([e.data])),o=document.createElement("a");o.href=r,o.download=`categories_${new Date().getTime()}.${t}`,document.body.appendChild(o),o.click(),o.remove(),window.URL.revokeObjectURL(r)}catch(e){throw console.error("Export failed:",e),new Error("Export failed")}}};export{c as C};
